#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

struct step {
	ll value; int cost;
	bool operator<(const step &other) const {
		return other.cost < cost;
	}
};

unordered_set<ll> visitedSet;

bool checkVisited(ll c) {
	return visitedSet.count(c) > 0;
}

step findUupper(ll n){
	ll res = 0;
	int count = 0;
	while(res < n){
		res = res * 10 + 1;
		count++;
	}
	return {res, count};
}

step findUpperBound(ll n){
	ll res = 0;
	int count = 0;
	while(res * 10 + 1 <= n){
		res = res * 10 + 1;
		count++;
	}
	ll baseRes = res;
	int baseCount = count;
	while(res < n){
		res += baseRes;
		count += baseCount;
	}
	return {res, count};
}

step findLowerBound(ll n){
	ll res = 0;
	int count = 0;
	while(res * 10 + 1 <= n){
		res = res * 10 + 1;
		count++;
	}
	ll baseRes = res;
	int baseCount = count;
	while(res + baseRes <= n){
		res += baseRes;
		count += baseCount;
	}
	return {res, count};
}

int main() {
	ll n;
	cin >> n;

	priority_queue<step> pq;

	pq.push({n, 0});

	while(pq.top().value != 0){
		ll val = pq.top().value;
		int cst = pq.top().cost;
		pq.pop();

		if(checkVisited(val))
			continue;
		visitedSet.insert(val);

		for (auto s : { findLowerBound(val), findUpperBound(val), findUupper(val) }) {
			s.cost += cst;
			s.val = abs(val - s.val);
			pq.push(s);
		}
	}

	cout << pq.top().cost << endl;
}
